/** Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Adapted from foglamp-labs/foglamp apps/web/src/components/app/app-shell.tsx under Apache-2.0.
 */
"use client";

import { useState, type ReactNode } from "react";
import { IconChartBar, IconChevronDown, IconChevronRight, IconLogout, IconPlus, type Icon } from "@tabler/icons-react";
import { cn } from "../../lib/utils";
import { FoglampLink } from "../../lib/link-context";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from "../../ui/dropdown-menu";
import { Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupContent, SidebarHeader, SidebarInset, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarProvider } from "../../ui/sidebar";
import { FoggyLauncher, FoggyWidget, type FoggyWidgetViewProps } from "../../widgets/foggy/index";
import { HeaderActionsSlotProvider, LayoutReserveProvider } from "../../widgets/header-slot";
import { account, nav } from "../../widgets/nav";
import { ProjectProvider, useProject, type Project } from "../../widgets/project-context";
import { ProjectIcon } from "../../widgets/leaf/project-icon";
import { RangeProvider } from "../../widgets/range-context";
import { NoProject } from "../../widgets/page-parts";
import { Avatar, AvatarFallback, AvatarImage } from "../../ui/avatar";
import { ThemeSubmenu } from "../../widgets/theme-switcher";
import { QuotaCard, type QuotaUsage } from "../../widgets/quota-card";
import { DevBar, type DevBarViewProps } from "../../widgets/dev-toolbar";
import { FoglampHUD, type FoglampHUDProps } from "../../hud/FoglampHUD";
import { createMockHudStream } from "../../hud/useHudStream";
import { NewProjectDialog, type NewProjectInput } from "./new-project-dialog";
import { SunsetCard } from "./sunset-card";
const BUILD_ENV = (import.meta as ImportMeta & { env?: { DEV?: boolean } }).env;
const RUNTIME_ENV = (globalThis as typeof globalThis & {
  process?: { env?: { NODE_ENV?: string; NEXT_PUBLIC_SERVER_URL?: string } };
}).process?.env;
const DEVELOPMENT = BUILD_ENV?.DEV ?? (RUNTIME_ENV?.NODE_ENV === "development");
const DEFAULT_SERVER_URL = RUNTIME_ENV?.NEXT_PUBLIC_SERVER_URL;
const DEFAULT_PROJECTS: Project[] = [{ id: "project_demo", name: "Acme Production", slug: "acme-production", url: null, orgId: "org_demo", orgName: "Acme", orgSlug: "acme" }];
const MOCK_HUD_STREAM = createMockHudStream([
  { type: "trace.start", ts: 0, traceId: "tr_9f2a4c8e1b7d3a6f5e0c", name: "support-triage", agentName: "support-triage", workflowName: "onboard-customer", sessionId: "ses_a91f" },
  { type: "step.start", ts: 120, traceId: "tr_9f2a4c8e1b7d3a6f5e0c", stepNumber: 1, provider: "google", model: "gemini-3.5-flash" },
  { type: "step.tokens", ts: 1040, traceId: "tr_9f2a4c8e1b7d3a6f5e0c", stepNumber: 1, outputTokens: 142 },
]);

export type AppShellBlockProps = {
  children: ReactNode;
  pathname?: string;
  projects?: Project[];
  initialProjectId?: string | null;
  isLoading?: boolean;
  onProjectChange?: (id: string) => void;
  onNewProject?: (input: NewProjectInput) => Project | Promise<Project>;
  projectDialogOpen?: boolean;
  onProjectDialogOpenChange?: (open: boolean) => void;
  serverUrl?: string;
  quotaUsage?: QuotaUsage | null;
  devBar?: DevBarViewProps;
  hud?: FoglampHUDProps;
  isPlatformAdmin?: boolean;
  foggy?: Omit<FoggyWidgetViewProps, "open" | "onOpenChange">;
  footer?: ReactNode;
  user?: { name: string; email?: string; image?: string };
  onSignOut?: () => void;
};

function NavIcon({ icon: OutlineIcon, activeIcon: ActiveIcon, active, className }: { icon: Icon; activeIcon: Icon; active: boolean; className?: string }) {
  return <span className={cn("grid size-4.5 place-items-center [&_svg]:size-full!", className)}>
    <OutlineIcon className={cn("[grid-area:1/1] transition-opacity duration-100 ease-in-out", active ? "opacity-0" : "opacity-100")} />
    <ActiveIcon className={cn("[grid-area:1/1] transition-opacity duration-100 ease-in-out", active ? "opacity-100" : "opacity-0")} />
  </span>;
}

function ProjectSwitcher({ onCreate, open, onOpenChange }: { onCreate: (input: NewProjectInput, fallback: Project) => Promise<Project>; open: boolean; onOpenChange: (open: boolean) => void }) {
  const { project, projects, setProjectId } = useProject();
  return <SidebarMenu><SidebarMenuItem><DropdownMenu>
    <DropdownMenuTrigger render={<SidebarMenuButton size="default" className="px-1 pr-2 pl-1.75 [&_svg]:size-3.5" />}>
      <ProjectIcon url={project?.url} name={project?.name} size="sm" />
      <div className="flex flex-1 flex-col text-left text-sm leading-tight"><span className="truncate font-medium">{project?.name ?? "Select project"}</span></div>
      <IconChevronDown className="ml-auto size-3.5 opacity-15" />
    </DropdownMenuTrigger>
    <DropdownMenuContent align="start" sideOffset={8} side="right" className="min-w-(--anchor-width)">
      {projects.map((p) => <DropdownMenuItem key={p.id} onClick={() => setProjectId(p.id)}><ProjectIcon url={p.url} name={p.name} size="sm" /><div className="flex flex-1 flex-col"><span>{p.name}</span></div></DropdownMenuItem>)}
    <DropdownMenuSeparator /><DropdownMenuItem onClick={() => onOpenChange(true)}><IconPlus />New project</DropdownMenuItem>
    </DropdownMenuContent>
  </DropdownMenu><NewProjectDialog open={open} onOpenChange={onOpenChange} onCreate={onCreate} /></SidebarMenuItem></SidebarMenu>;
}

function NavUser({ user, onSignOut, isPlatformAdmin }: Pick<AppShellBlockProps, "user" | "onSignOut" | "isPlatformAdmin">) {
  const name = user?.name || "Account";
  return <SidebarMenuItem><DropdownMenu>
    <DropdownMenuTrigger render={<SidebarMenuButton className="pr-1.5" />}>
      <Avatar size="xs"><AvatarImage src={user?.image} alt={name} /><AvatarFallback>{name.slice(0, 2).toUpperCase()}</AvatarFallback></Avatar>
      <div className="flex min-w-0 flex-1 flex-col text-left text-sm"><span className="truncate">{name}</span></div>
      <IconChevronRight className="ml-auto size-3.5 opacity-15" />
    </DropdownMenuTrigger>
    <DropdownMenuContent align="end" side="right" sideOffset={8} className="min-w-(--anchor-width) w-fit">
      <div className="flex gap-3 items-center p-2"><Avatar size="sm"><AvatarImage src={user?.image} alt={name} /><AvatarFallback>{name.slice(0, 2).toUpperCase()}</AvatarFallback></Avatar><div className="flex flex-col gap-0.5 pr-1"><DropdownMenuLabel className="max-w-56 truncate p-0 text-foreground">{name}</DropdownMenuLabel><DropdownMenuLabel className="max-w-56 truncate p-0 font-normal">{user?.email}</DropdownMenuLabel></div></div>
      <DropdownMenuSeparator /><ThemeSubmenu />
      {isPlatformAdmin && <DropdownMenuItem render={<FoglampLink href="/platform" />}><IconChartBar />Platform</DropdownMenuItem>}
      <DropdownMenuItem variant="destructive" onClick={onSignOut}><IconLogout />Log out</DropdownMenuItem>
    </DropdownMenuContent>
  </DropdownMenu></SidebarMenuItem>;
}

function ShellBody({ children, pathname = "/overview", foggy, footer, user, onSignOut, isPlatformAdmin, serverUrl = DEFAULT_SERVER_URL, quotaUsage, devBar, hud, onCreate, projectDialogOpen, onProjectDialogOpenChange }: Omit<AppShellBlockProps, "projects" | "initialProjectId" | "isLoading" | "onProjectChange" | "onNewProject"> & { onCreate: (input: NewProjectInput, fallback: Project) => Promise<Project> }) {
  const [localDialogOpen, setLocalDialogOpen] = useState(false);
  const dialogOpen = projectDialogOpen ?? localDialogOpen;
  const setDialogOpen = (open: boolean) => { if (projectDialogOpen === undefined) setLocalDialogOpen(open); onProjectDialogOpenChange?.(open); };
  const { projectId, projects, isLoading } = useProject();
  const [foggyOpen, setFoggyOpen] = useState(false);
  const foggyCarved = (isLoading || projects.length > 0) && !foggyOpen;
  function menu(items: typeof nav) {
    return items.map((item) => {
      const active = item.href === "/settings" ? pathname === item.href : pathname === item.href || pathname.startsWith(`${item.href}/`);
      return <SidebarMenuItem key={item.href}><SidebarMenuButton isActive={active} render={<FoglampLink href={item.href} />}><NavIcon icon={item.icon} activeIcon={item.activeIcon} active={active} className={item.iconClassName} /><span>{item.label}</span></SidebarMenuButton></SidebarMenuItem>;
    });
  }
  return <SidebarProvider className="group/shell relative h-svh min-h-0 overflow-hidden">
    <Sidebar variant="inset"><SidebarHeader><ProjectSwitcher onCreate={onCreate} open={dialogOpen} onOpenChange={setDialogOpen} /></SidebarHeader>
      <SidebarContent><SidebarGroup><SidebarGroupContent><SidebarMenu>{menu(nav)}</SidebarMenu></SidebarGroupContent></SidebarGroup></SidebarContent>
      <SidebarFooter><SunsetCard serverUrl={serverUrl} /><QuotaCard usage={quotaUsage} /><SidebarMenu>{menu(account)}<NavUser user={user} onSignOut={onSignOut} isPlatformAdmin={isPlatformAdmin} />{footer}</SidebarMenu></SidebarFooter>
    </Sidebar>
    <div className="flex min-h-0 min-w-0 flex-1 flex-col gap-2 md:peer-data-[variant=inset]:m-2 md:peer-data-[variant=inset]:ml-0 md:peer-data-[variant=inset]:peer-data-[state=collapsed]:ml-2">
      {DEVELOPMENT && <DevBar {...devBar} />}
      <SidebarInset className={cn("min-h-0 overflow-hidden transition-shadow duration-200 md:rounded-lg squircle:md:rounded-3xl", foggyCarved && "foggy-inset-closed")} style={foggyCarved ? { borderBottomRightRadius: 0 } : undefined}>
        <main className="min-h-0 flex-1 overflow-y-auto"><div className="flex flex-col gap-4 py-6 px-0 pb-16">{projectId ? children : !isLoading && projects.length === 0 ? <NoProject /> : null}</div></main>
        <div aria-hidden className="pointer-events-none absolute inset-0 z-10 rounded-lg squircle:rounded-3xl corner-squircle border-r border-border/80 opacity-0 transition-opacity duration-200 group-has-[[data-foggy-resize]:hover]/shell:opacity-100 group-has-[[data-foggy-resize][data-resizing]]/shell:opacity-100" />
      </SidebarInset>
    </div>
    {foggyCarved && <FoggyLauncher onOpen={() => setFoggyOpen(true)} showButton={Boolean(projectId)} />}
    {projectId && <FoggyWidget key={projectId} {...foggy} open={foggyOpen} onOpenChange={setFoggyOpen} />}
    {DEVELOPMENT && <FoglampHUD stream={MOCK_HUD_STREAM} {...hud} />}
  </SidebarProvider>;
}

export function AppShellBlock({ projects = DEFAULT_PROJECTS, initialProjectId, isLoading, onProjectChange, onNewProject, ...props }: AppShellBlockProps) {
  const [createdProjects, setCreatedProjects] = useState<Project[]>([]);
  const availableProjects = [...projects, ...createdProjects.filter((created) => !projects.some((project) => project.id === created.id))];
  async function createProject(input: NewProjectInput, fallback: Project): Promise<Project> {
    const project = onNewProject ? await onNewProject(input) : fallback;
    setCreatedProjects((current) => [...current, project]);
    return project;
  }
  return <ProjectProvider projects={availableProjects} initialProjectId={initialProjectId} isLoading={isLoading} onProjectChange={onProjectChange}><RangeProvider><HeaderActionsSlotProvider><LayoutReserveProvider><ShellBody {...props} onCreate={createProject} /></LayoutReserveProvider></HeaderActionsSlotProvider></RangeProvider></ProjectProvider>;
}

/** Integration exports for the Foglamp Design System.
 * Original Foglamp UI and design by Gustavo Fior (@gustavo-fior), Abdul Haidar and Foglamp Labs; Apache-2.0.
 */
export { AppShellBlock } from "./app-shell-block";
export type { AppShellBlockProps } from "./app-shell-block";
export { NewProjectDialog } from "./new-project-dialog";
export type { NewProjectInput } from "./new-project-dialog";
export { SunsetCard } from "./sunset-card";

/** Original design and implementation by Gustavo Fior (@gustavo-fior), Abdul Haidar and Foglamp Labs.
 * Adapted from foglamp-labs/foglamp apps/web/src/components/app/new-project-dialog.tsx under Apache-2.0.
 */
"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Button } from "../../ui/button";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "../../ui/dialog";
import { Field, FieldLabel } from "../../ui/field";
import { Input } from "../../ui/input";
import { useProject, type Project } from "../../widgets/project-context";

export type NewProjectInput = { orgId: string; name: string; url?: string };
export function NewProjectDialog({ open, onOpenChange, onCreate }: { open: boolean; onOpenChange: (open: boolean) => void; onCreate: (input: NewProjectInput, project: Project) => Promise<Project> }) {
  const { project, setProjectId } = useProject();
  const [name, setName] = useState("");
  const [url, setUrl] = useState("");
  const [pending, setPending] = useState(false);
  async function create() {
    if (!name.trim() || !project?.orgId || pending) return;
    setPending(true);
    try {
      const input = { orgId: project.orgId, name: name.trim(), url: url.trim() || undefined };
      const created: Project = { ...project, id: `project_${globalThis.crypto.randomUUID()}`, name: input.name, slug: input.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""), url: input.url ?? null };
      const result = await onCreate(input, created);
      setProjectId(result.id);
      onOpenChange(false);
      setName("");
      setUrl("");
      toast.success("Project created");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Unable to create project");
    } finally {
      setPending(false);
    }
  }
  return <Dialog open={open} onOpenChange={onOpenChange}>
    <DialogContent>
      <DialogHeader><DialogTitle>New project</DialogTitle></DialogHeader>
      <Field><FieldLabel>Name</FieldLabel><Input autoFocus placeholder="My project" value={name} onChange={(e) => setName(e.target.value)} /></Field>
      <Field><FieldLabel className="gap-1.5">URL<span className="text-muted-foreground font-normal">(optional)</span></FieldLabel><Input placeholder="example.com" value={url} onChange={(e) => setUrl(e.target.value)} /></Field>
      <DialogFooter><Button disabled={!name.trim() || !project?.orgId || pending} onClick={create}>Create</Button></DialogFooter>
    </DialogContent>
  </Dialog>;
}

/** Original design and implementation by Gustavo Fior (@gustavo-fior), Abdul Haidar and Foglamp Labs.
 * Adapted from foglamp-labs/foglamp apps/web/src/components/app/sunset-card.tsx under Apache-2.0.
 */
"use client";
import { IconSunsetFilled } from "@tabler/icons-react";

export function SunsetCard({ serverUrl }: { serverUrl?: string }) {
  if (serverUrl !== "https://api.foglamp.dev") return null;
  return <div className="mb-1 flex flex-col gap-1.5 rounded-3xl squircle:rounded-[40px] corner-squircle border border-amber-500/10 bg-amber-500/10 p-3 px-3.5 text-xs text-amber-700 dark:text-amber-400">
    <div className="flex items-center gap-1.5"><IconSunsetFilled className="size-3" /><span className="font-medium text-[13px]">Foglamp is sunsetting</span></div>
    <p>The hosted service stops on October 18, 2026 and all data will be deleted. Want an export? <a href="mailto:gustavo@foglamp.dev" className="underline">Email us</a>.</p>
  </div>;
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/hooks/use-mobile.ts; derived here under Apache-2.0.
 */
import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

/**
 * Original UI & design: Gustavo Fior (@gustavo-fior), Abdul Haidar & Foglamp Labs.
 * Extracted from https://github.com/foglamp-labs/foglamp — Apache-2.0.
 */
"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from "react";
import { createPortal } from "react-dom";

import { formatCost, formatDuration, formatTokens, formatTps } from "./format";
import {
  rows,
  type HudRow,
  type HudStep,
  type HudToolCall,
  type HudTrace,
} from "./model";
import { ModelLogo, formatModelName } from "./model-logo";
import { HUD_CSS } from "./styles";
import { useHudStream, type ConnStatus, type HudStream } from "./useHudStream";

export interface FoglampHUDProps {
  /** Optional local/mock event source. No connection is opened by default. */
  stream?: HudStream;
  /** Start expanded (otherwise starts as the pill). Default false. */
  defaultOpen?: boolean;
  /** Color theme. "system" follows the host app (its `.dark` class) / OS. Default "system". */
  theme?: "light" | "dark" | "system";
  /** Mask prompt/response/tool payloads on screen — set before recording or screen-sharing. */
  redact?: boolean;
}

type Mode = "pill" | "expanded";
type StatusKind = "" | "run" | "err";

// The timeline's auto-follow scroll must run synchronously after the DOM grows
// (before paint) so the scroll position and the wider track commit together — an
// async useEffect leaves a one-frame gap where the grid lines jump. Fall back to
// useEffect on the server to avoid the SSR layout-effect warning.
const useIsoLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;
// Shell size springs — pill↔expanded is fast + snappy; list↔detail a touch
// softer. Driven by the vendored micro-spring below (no motion dependency).
// Views themselves just cross-fade (CSS, see .fl-mode).
const SPRING_PILL = { stiffness: 620, damping: 42 } as const;
const SPRING_VIEW = { stiffness: 540, damping: 44 } as const;

type Size = { w: number; h: number };
type SpringParams = { stiffness: number; damping: number };

/**
 * A tiny rAF spring that tweens width+height toward a target — the morph's whole
 * reason for ever needing `motion`. The first target snaps (no animation on
 * mount); later targets spring with a small overshoot (damping < critical).
 * Integrated at a fixed 1/240s sub-step so the stiff springs stay stable
 * regardless of frame rate. Retargets mid-flight (reads the latest target/params
 * via refs). No `Date.now`/`Math.random` — rAF timestamps only.
 */
function useSizeSpring(target: Size | undefined, params: SpringParams): Size | undefined {
  const [val, setVal] = useState<Size | undefined>(target);
  const cur = useRef<{ w: number; h: number; vw: number; vh: number } | null>(null);
  const targetRef = useRef(target);
  const paramsRef = useRef(params);
  const raf = useRef<number | null>(null);
  const last = useRef(0);
  targetRef.current = target;
  paramsRef.current = params;

  useEffect(() => {
    if (!target) return;
    // First measured size: snap into place, no animation.
    if (!cur.current) {
      cur.current = { w: target.w, h: target.h, vw: 0, vh: 0 };
      setVal({ w: target.w, h: target.h });
      return;
    }
    if (raf.current != null) return; // a loop is already chasing the (updated) target
    last.current = 0;
    const tick = (ts: number) => {
      const s = cur.current!;
      const tg = targetRef.current!;
      const { stiffness, damping } = paramsRef.current;
      let dt = last.current ? (ts - last.current) / 1000 : 1 / 60;
      last.current = ts;
      dt = Math.min(dt, 0.064); // clamp tab-switch gaps
      for (let t = dt; t > 0; t -= 1 / 240) {
        const h = Math.min(t, 1 / 240);
        s.vw += (-stiffness * (s.w - tg.w) - damping * s.vw) * h;
        s.w += s.vw * h;
        s.vh += (-stiffness * (s.h - tg.h) - damping * s.vh) * h;
        s.h += s.vh * h;
      }
      const settled =
        Math.abs(s.w - tg.w) < 0.5 && Math.abs(s.vw) < 1 &&
        Math.abs(s.h - tg.h) < 0.5 && Math.abs(s.vh) < 1;
      if (settled) {
        s.w = tg.w; s.h = tg.h; s.vw = 0; s.vh = 0;
        setVal({ w: tg.w, h: tg.h });
        raf.current = null;
        return;
      }
      setVal({ w: s.w, h: s.h });
      raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
  }, [target?.w, target?.h]);

  useEffect(
    () => () => {
      if (raf.current != null) cancelAnimationFrame(raf.current);
    },
    [],
  );

  return val;
}

// Per-agent bar colors for the timeline — a stable hash so the same agent keeps
// its color across runs (an error run overrides to the error red).
const TL_PALETTE = [
  "#10b981", // emerald
  "#3b82f6", // blue
  "#f59e0b", // amber
  "#8b5cf6", // violet
  "#ec4899", // pink
  "#06b6d4", // cyan
  "#f97316", // orange
  "#14b8a6", // teal
];
function tlColor(key: string): string {
  let h = 0;
  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;
  return TL_PALETTE[h % TL_PALETTE.length]!;
}

// Error runs override to a fixed rose (reads on both themes); fine as a hex
// since the timeline bars set `background` directly.
const TL_ERROR = "#f43f5e";

// Per-agent glyphs — simple filled shapes that read at ~12px. Paired with a
// separate hash (multiplier 37 vs the color's 31) so each agent gets an
// independent, stable (icon, color) from the two pools.
const TL_ICONS = [
  "M13 2 4 14h6l-1 8 9-12h-6z", // bolt
  "M12 2c.6 5.4 2.9 7.7 8.3 8.3-5.4.6-7.7 2.9-8.3 8.3-.6-5.4-2.9-7.7-8.3-8.3 5.4-.6 7.7-2.9 8.3-8.3z", // sparkle
  "M12 2 21 12 12 22 3 12z", // diamond
  "M12 3 22 20H2z", // triangle
  "M12 2.4 20.6 7.2v9.6L12 21.6 3.4 16.8V7.2z", // hexagon
  "M9.5 3h5a6.5 6.5 0 0 1 6.5 6.5v5a6.5 6.5 0 0 1-6.5 6.5h-5A6.5 6.5 0 0 1 3 14.5v-5A6.5 6.5 0 0 1 9.5 3z", // squircle
  "M10 3h4v7h7v4h-7v7h-4v-7H3v-4h7z", // plus
  "M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18z", // circle
];
function tlIcon(key: string): string {
  let h = 0;
  for (let i = 0; i < key.length; i++) h = (h * 37 + key.charCodeAt(i)) >>> 0;
  return TL_ICONS[h % TL_ICONS.length]!;
}

// A bg-cutout warning triangle (filled triangle with an evenodd "!" punched
// out) — shown on error pills instead of the agent glyph.
const WARN_GLYPH = "M12 3 22.5 21H1.5z M11 9h2v6h-2z M11 16.5h2v2.5h-2z";

// Errors in a trace = failed tool calls + failed steps (≥1 if the run itself
// errored without a pinpointed sub-failure).
function errorCount(t: HudTrace): number {
  const n =
    t.tools.filter((x) => x.status === "error").length +
    t.steps.filter((x) => x.status === "error").length;
  return n > 0 ? n : t.status === "error" ? 1 : 0;
}

function traceColor(t: HudTrace): string {
  return t.status === "error" ? TL_ERROR : tlColor(t.agentName ?? t.name);
}

// The timeline shows a fixed 1-minute window; longer sessions scroll. Zoom is
// constant (1 min = the viewport), so runs whose starts land within ~2.7s pile
// up on the same spot → cluster them into one marker.
const WINDOW_MS = 60_000;
const CLUSTER_GAP_MS = WINDOW_MS * 0.045;
const TICK_MS = 15_000; // vertical grid every 15s
// A little gutter past `now` on the right so the live pill isn't glued to the
// edge. In the time domain (not CSS padding, which a scroll container eats at
// the scroll-end); scales with zoom to a constant ~14px.
const RIGHT_PAD_MS = WINDOW_MS * 0.035;

/** Compact "how long ago" label for an axis tick (0 = now). */
function tickLabel(ago: number): string {
  if (ago === 0) return "now";
  const s = Math.round(ago / 1000);
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  const r = s % 60;
  return r ? `${m}m ${r}s` : `${m}m`;
}

/** Group runs whose starts are within CLUSTER_GAP_MS (time-sorted, ascending). */
function clusterRuns(traces: HudTrace[]): HudTrace[][] {
  const sorted = [...traces].sort((a, b) => a.startedAt - b.startedAt);
  const groups: HudTrace[][] = [];
  for (const t of sorted) {
    const last = groups[groups.length - 1];
    if (last && t.startedAt - last[last.length - 1]!.startedAt <= CLUSTER_GAP_MS) {
      last.push(t);
    } else {
      groups.push([t]);
    }
  }
  return groups;
}

/**
 * Floating overlay that streams live agent execution from the local Foglamp
 * broker. Renders into a Shadow DOM root appended to <body> so its styles are
 * fully isolated from (and can't be restyled by) the host app. Dev-only: inert
 * unless a broker is running (`foglamp({ hud: true })`).
 */
export function FoglampHUD(props: FoglampHUDProps): ReactNode {
  const [mount, setMount] = useState<HTMLElement | null>(null);
  const hostRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (typeof document === "undefined") return;
    const host = document.createElement("foglamp-hud");
    const shadow = host.attachShadow({ mode: "open" });
    const style = document.createElement("style");
    style.textContent = HUD_CSS;
    shadow.appendChild(style);
    const mountEl = document.createElement("div");
    shadow.appendChild(mountEl);
    document.body.appendChild(host);
    hostRef.current = host;
    setMount(mountEl);
    return () => {
      host.remove();
      hostRef.current = null;
    };
  }, []);

  const theme = useResolvedTheme(props.theme ?? "system");
  useEffect(() => {
    hostRef.current?.setAttribute("data-theme", theme);
  }, [theme, mount]);

  if (!mount) return null;
  return createPortal(<HudApp {...props} />, mount);
}

/** Resolve the active theme, following the host app's `.dark`/`data-theme` and OS. */
function useResolvedTheme(
  theme: "light" | "dark" | "system"
): "light" | "dark" {
  const [resolved, setResolved] = useState<"light" | "dark">("light");
  useEffect(() => {
    if (theme !== "system") {
      setResolved(theme);
      return;
    }
    const root = document.documentElement;
    const compute = (): "light" | "dark" => {
      if (root.classList.contains("dark")) return "dark";
      if (root.classList.contains("light")) return "light";
      const attr = root.getAttribute("data-theme");
      if (attr === "dark" || attr === "light") return attr;
      return window.matchMedia("(prefers-color-scheme: dark)").matches
        ? "dark"
        : "light";
    };
    setResolved(compute());
    const mo = new MutationObserver(() => setResolved(compute()));
    mo.observe(root, {
      attributes: true,
      attributeFilter: ["class", "data-theme"],
    });
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const onChange = () => setResolved(compute());
    mq.addEventListener("change", onChange);
    return () => {
      mo.disconnect();
      mq.removeEventListener("change", onChange);
    };
  }, [theme]);
  return resolved;
}

// sessionStorage flag: "1" = the user hid the HUD for this browser session.
const HIDE_KEY = "foglamp-hud-hidden";

function HudApp(props: FoglampHUDProps) {
  const { state, conn } = useHudStream(props.stream);
  const [mode, setMode] = useState<Mode>(
    props.defaultOpen ? "expanded" : "pill"
  );
  // Hidden-for-session: seeded from sessionStorage so the choice survives
  // reloads (but not a new tab/session). Guarded — storage can throw in
  // sandboxed iframes.
  const [hidden, setHidden] = useState(() => {
    try {
      return sessionStorage.getItem(HIDE_KEY) === "1";
    } catch {
      return false;
    }
  });
  // The red "hide for this session?" confirmation: null → hidden, "open" →
  // showing, "closing" → playing its exit animation before unmounting (the
  // reverse of the entrance wipe; see .fl-hide-alert.closing).
  const [hideAlert, setHideAlert] = useState<"open" | "closing" | null>(null);
  const confirmHide = () => {
    try {
      sessionStorage.setItem(HIDE_KEY, "1");
    } catch {
      // Storage unavailable — still hide for this page's lifetime.
    }
    setHidden(true);
  };
  const [selectedId, setSelectedId] = useState<string | null>(null);
  // Slide direction for the list↔detail transition: +1 forward (into a run),
  // -1 back (to the list), 0 for pill ↔ expanded (fade only).
  const [direction, setDirection] = useState(0);
  const traces = state.traces;
  const running = traces.some((t) => t.status === "running");
  const pillStatus: StatusKind = running
    ? "run"
    : traces[0]?.status === "error"
      ? "err"
      : "";

  // Tick while running so live durations advance and the timeline follows `now`.
  // ~50ms: the follow offset is sub-pixel-accurate per tick (scroll floor + a
  // fractional transform), so a faster tick just shrinks each step → smoother.
  const [, force] = useState(0);
  useEffect(() => {
    if (!running) return;
    const id = setInterval(() => force((n) => n + 1), 50);
    return () => clearInterval(id);
  }, [running]);

  const expand = () => {
    // Open to the trace list; tap a run to drill into its detail.
    setDirection(0);
    setSelectedId(null);
    setMode("expanded");
  };
  const select = (id: string) => {
    setDirection(1);
    setSelectedId(id);
  };
  const back = () => {
    setDirection(-1);
    setSelectedId(null);
  };
  const collapse = () => {
    setDirection(0);
    setHideAlert(null); // don't leave the alert floating over the pill
    setMode("pill");
  };

  // Esc steps back: detail → list → pill.
  useEffect(() => {
    if (mode !== "expanded") return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      if (selectedId) back();
      else collapse();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [mode, selectedId]);

  const selected = selectedId
    ? traces.find((t) => t.traceId === selectedId)
    : undefined;
  const viewKey =
    mode === "pill" ? "pill" : selected ? `detail:${selected.traceId}` : "list";

  if (hidden) return null;

  return (
    <>
      {hideAlert && (
        <HideAlert
          closing={hideAlert === "closing"}
          onConfirm={confirmHide}
          onCancel={() => setHideAlert("closing")}
          onClosed={() => setHideAlert(null)}
        />
      )}
      <Morph dataMode={mode} viewKey={viewKey} direction={direction}>
        {mode === "pill" ? (
          <Pill count={state.sessionCount} status={pillStatus} onExpand={expand} />
        ) : selected ? (
          <TraceDetail
            trace={selected}
            redact={props.redact ?? false}
            onBack={back}
            onCollapse={collapse}
          />
        ) : (
          <TraceList
            traces={traces}
            sessionCount={state.sessionCount}
            conn={conn}
            status={pillStatus}
            onSelect={select}
            onCollapse={collapse}
            onHideRequest={() =>
              setHideAlert((v) => (v === "open" ? "closing" : "open"))
            }
          />
        )}
      </Morph>
    </>
  );
}

/** Red confirmation bar shown above the window before hiding the HUD for the
 * rest of the browser session (see HIDE_KEY). While `closing`, it plays the
 * entrance animation in reverse and reports `onClosed` when it finishes so the
 * owner can unmount it. */
function HideAlert({
  closing,
  onConfirm,
  onCancel,
  onClosed,
}: {
  closing: boolean;
  onConfirm: () => void;
  onCancel: () => void;
  onClosed: () => void;
}) {
  return (
    <div
      className={`fl-hide-alert ${closing ? "closing" : ""}`}
      role="alertdialog"
      aria-label="Hide Foglamp HUD"
      // Only the exit animation runs while `closing` (it overrides the pulse),
      // so any animationend in that state means the exit finished.
      onAnimationEnd={() => {
        if (closing) onClosed();
      }}
    >
      <WarnIcon />
      <span className="fl-hide-alert-text">Hide the HUD for this session?</span>
      <button type="button" className="fl-hide-btn" onClick={onCancel}>
        Keep
      </button>
      <button type="button" className="fl-hide-btn confirm" onClick={onConfirm}>
        Hide
      </button>
    </div>
  );
}

/**
 * The shell springs its width/height to the *entering* view's measured size
 * (snapped on first paint, tweened after). Views cross-fade via CSS: the inner
 * `.fl-mode` is keyed on the view, so React remounts it on every change and its
 * fade-in keyframe replays. Measuring the entering element directly (it's
 * `width: max-content`, so its natural size is unaffected by the shell's
 * animated width) lets the shell resize from the start of the transition.
 */
function Morph({
  dataMode,
  viewKey,
  direction,
  children,
}: {
  dataMode: Mode;
  viewKey: string;
  direction: number;
  children: ReactNode;
}) {
  const [size, setSize] = useState<Size>();
  const roRef = useRef<ResizeObserver | null>(null);

  // Measure the entering view directly and keep tracking it (live streaming rows
  // grow the list). `.fl-mode` is `width: max-content`, so this reads the view's
  // natural size even while the shell's own width is mid-spring.
  const measureRef = useCallback((el: HTMLDivElement | null) => {
    if (!el) return;
    roRef.current?.disconnect();
    const measure = () => setSize({ w: el.offsetWidth, h: el.offsetHeight });
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    roRef.current = ro;
  }, []);
  useEffect(() => () => roRef.current?.disconnect(), []);

  const animSize = useSizeSpring(size, direction === 0 ? SPRING_PILL : SPRING_VIEW);

  return (
    <div
      className="fl-shell"
      data-mode={dataMode}
      style={animSize ? { width: animSize.w, height: animSize.h } : undefined}
    >
      <div key={viewKey} ref={measureRef} className="fl-mode">
        {children}
      </div>
    </div>
  );
}

function Pill({
  count,
  status,
  onExpand,
}: {
  count: number;
  status: StatusKind;
  onExpand: () => void;
}) {
  return (
    // The whole pill (brand, count, diamond) is the expand target.
    <div
      className="fl-pill"
      role="button"
      tabIndex={0}
      onClick={onExpand}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onExpand();
        }
      }}
      aria-label="Expand Foglamp HUD"
    >
      <BrandMark className="fl-brand" />
      {count > 0 && <span className="fl-count">{count}</span>}
      <Diamond status={status} />
    </div>
  );
}

// A small colored circle with the agent's glyph — the agent's identity, shared
// with the timeline (same color + icon hashes). Pure identity, no error tint.
function AgentBadge({ name }: { name: string }) {
  return (
    <span className="fl-agent-badge" style={{ background: tlColor(name) }}>
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path d={tlIcon(name)} />
      </svg>
    </span>
  );
}

/**
 * A live timeline of the session's runs on a single shared axis: every run is a
 * pill on one line (concurrent runs overlap), tagged with the agent's icon and
 * color so you can tell them apart. While a run is live the window tracks `now`
 * (auto-scaling) and the pills CSS-transition so the ~100ms ticks read as
 * continuous motion. Tap a pill to open its detail.
 */
function TraceTimeline({
  traces,
  onSelect,
  scrollRef,
  onScroll,
  followingRef,
}: {
  traces: HudTrace[];
  onSelect: (id: string) => void;
  scrollRef: RefObject<HTMLDivElement | null>;
  onScroll: () => void;
  followingRef: RefObject<boolean>;
}) {
  // Freeze `now` whenever we're not live-following, so scrolling back to a past
  // period shows a fully static chart (no axis creep) until you return to the edge.
  const frozenNow = useRef(Date.now());
  const liveNow = Date.now();
  const now = followingRef.current ? liveNow : frozenNow.current;
  if (followingRef.current) frozenNow.current = liveNow;

  const sessionStart = traces.length ? Math.min(...traces.map((t) => t.startedAt)) : now;
  const dataMs = Math.max(now - sessionStart, WINDOW_MS);
  const windowStart = now - dataMs; // left edge = oldest run (or 1 min back)
  const totalMs = dataMs + RIGHT_PAD_MS; // track spans the data + the right gutter
  const clusters = clusterRuns(traces);

  // Lay the track out in FIXED pixels (a constant px/ms scale), not % of a
  // growing track. With %, each tick the content drifts sub-pixel while the
  // integer scrollLeft steps — the two never agree and the chart "dances" ±1px.
  // Fixed px + wall-clock-anchored grid lines hold everything still; only the
  // scroll advances to follow `now`.
  // While the session has no traces this component renders null, so on the
  // first run of this effect the scroll element may not exist yet. `hasTraces`
  // re-fires it on the empty→populated flip (the commit that mounts the
  // element); without that dep vw stays 0 and every tick/label/marker lands at
  // left: 0 in a pile.
  const hasTraces = traces.length > 0;
  const [vw, setVw] = useState(0);
  useIsoLayoutEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    const measure = () => setVw(el.clientWidth);
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [scrollRef, hasTraces]);
  const pxPerMs = vw > 0 ? vw / WINDOW_MS : 0;
  const trackW = totalMs * pxPerMs;
  const x = (t: number) => (t - windowStart) * pxPerMs; // px from the track's left

  // 15s grid at wall-clock-aligned times (fixed positions), labelled by age.
  const ticks: number[] = [];
  for (let g = Math.ceil(windowStart / TICK_MS) * TICK_MS; g <= now; g += TICK_MS) ticks.push(g);

  // Follow the right edge while `following`; layout-effect re-pins atomically
  // with the track growth (an async effect would leave a one-frame jump).
  // scrollLeft is integer-only, so the view would jump a whole pixel each step —
  // pin scroll to the floor and carry the sub-pixel remainder on the track's
  // transform, so the follow is smooth instead of stair-stepping.
  const innerRef = useRef<HTMLDivElement>(null);
  const didInit = useRef(false);
  useIsoLayoutEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    const max = el.scrollWidth - el.clientWidth;
    if (!didInit.current) {
      el.scrollLeft = max;
      didInit.current = true;
    } else if (followingRef.current) {
      const floor = Math.floor(max);
      el.scrollLeft = floor;
      if (innerRef.current) innerRef.current.style.transform = `translateX(${floor - max}px)`;
    }
  }, [scrollRef, trackW, traces.length, followingRef]);

  if (traces.length === 0) return null;

  return (
    <div className="fl-timeline">
      <div className="fl-tl-scroll" ref={scrollRef} onScroll={onScroll}>
        <div className="fl-tl-inner" ref={innerRef} style={{ width: `${trackW}px` }}>
          <div className="fl-tl-track">
            <span className="fl-tl-axis" />
            {ticks.map((g) => (
              <span key={`g${g}`} className="fl-tl-grid" style={{ left: `${x(g)}px` }} />
            ))}
            <span className="fl-tl-grid now" style={{ left: `${x(now)}px` }} />
            {clusters.map((group) => {
              const left = x(group[0]!.startedAt);
            if (group.length === 1) {
              const t = group[0]!;
              const key = t.agentName ?? t.name;
              const isErr = t.status === "error";
              const end = t.endedAt ?? now;
              const width = Math.max((end - t.startedAt) * pxPerMs, 0);
              return (
                <button
                  key={t.traceId}
                  type="button"
                  className={`fl-tl-bar ${t.status === "running" ? "run" : ""}`}
                  style={{ left: `${left}px`, width: `${width}px`, background: traceColor(t) }}
                  onClick={() => onSelect(t.traceId)}
                  title={`${key} · ${formatDuration(end - t.startedAt)}`}
                >
                  <svg className="fl-tl-ico" viewBox="0 0 24 24" aria-hidden="true">
                    <path
                      d={isErr ? WARN_GLYPH : tlIcon(key)}
                      fillRule={isErr ? "evenodd" : "nonzero"}
                    />
                  </svg>
                </button>
              );
            }
            // Concurrent runs collapse into one marker (latest opens on click).
            // The marker spans the group's full extent: earliest start → latest end.
            const latest = group.reduce((a, b) => (b.startedAt > a.startedAt ? b : a));
            const names = group.map((t) => t.agentName ?? t.name).join(", ");
            const gEnd = Math.max(...group.map((t) => t.endedAt ?? now));
            const cWidth = Math.max((gEnd - group[0]!.startedAt) * pxPerMs, 0);
            return (
              <button
                key={group.map((t) => t.traceId).join("|")}
                type="button"
                className="fl-tl-cluster"
                style={{ left: `${left}px`, width: `${cWidth}px` }}
                onClick={() => onSelect(latest.traceId)}
                title={`${group.length} runs · ${names}`}
              >
                <span className="fl-tl-cdots">
                  {group.slice(0, 3).map((t) => {
                    const isErr = t.status === "error";
                    return (
                      <span
                        key={t.traceId}
                        className="fl-tl-cdot"
                        style={{ background: traceColor(t) }}
                      >
                        <svg viewBox="0 0 24 24" aria-hidden="true">
                          <path
                            d={isErr ? WARN_GLYPH : tlIcon(t.agentName ?? t.name)}
                            fillRule={isErr ? "evenodd" : "nonzero"}
                          />
                        </svg>
                      </span>
                    );
                  })}
                </span>
                <span className="fl-tl-cn">{group.length}</span>
              </button>
            );
            })}
          </div>
          <div className="fl-tl-axislabels">
            {ticks
              .filter((g) => now - g >= TICK_MS / 2) // skip marks hugging the now-tag
              .map((g) => (
                <span key={`l${g}`} className="fl-tl-tick" style={{ left: `${x(g)}px` }}>
                  {tickLabel(now - g)}
                </span>
              ))}
            <span className="fl-tl-tick now" style={{ left: `${x(now)}px` }}>
              now
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

/** The session's traces, newest first — tap one to open its detail. */
function TraceList({
  traces,
  sessionCount,
  conn,
  status,
  onSelect,
  onCollapse,
  onHideRequest,
}: {
  traces: HudTrace[];
  sessionCount: number;
  conn: ConnStatus;
  status: StatusKind;
  onSelect: (id: string) => void;
  onCollapse: () => void;
  onHideRequest: () => void;
}) {
  // The chart and the list scroll independently (a previous chart↔list sync fed
  // back into itself every tick and made the list jitter up/down). Live-follow
  // only while the chart is parked at the right edge (now); scrolling it left to
  // a past period sets `following` false, which both stops auto-advance and
  // freezes `now` (see TraceTimeline) until you scroll back to the edge.
  const chartRef = useRef<HTMLDivElement>(null);
  const following = useRef(true);
  const onChartScroll = () => {
    const c = chartRef.current;
    if (!c) return;
    const cMax = c.scrollWidth - c.clientWidth;
    following.current = cMax <= 1 || cMax - c.scrollLeft < 24;
  };

  return (
    <div className="fl-panel" role="dialog" aria-label="Foglamp traces">
      <div className="fl-header fl-header-list">
        <div className="fl-title">
          <b>Traces</b>
          <span>
            {sessionCount > 0
              ? `${sessionCount} this session`
              : conn === "open"
                ? "Waiting for a run…"
                : "connecting…"}
          </span>
        </div>
        <Diamond status={status} />
        <button
          type="button"
          className="fl-icon-btn"
          onClick={onHideRequest}
          aria-label="Hide HUD for this session"
        >
          <EyeOffIcon />
        </button>
        <button
          type="button"
          className="fl-icon-btn"
          onClick={onCollapse}
          aria-label="Collapse"
        >
          <ChevronDown />
        </button>
      </div>

      <TraceTimeline
        traces={traces}
        onSelect={onSelect}
        scrollRef={chartRef}
        onScroll={onChartScroll}
        followingRef={following}
      />

      <div className="fl-list">
        {traces.length === 0 ? (
          <div className="fl-empty">
            <span className="fl-listening" aria-hidden="true">
              <span />
              <span />
            </span>
            <p>{conn === "open" ? "Listening for runs…" : "Connecting to the broker…"}</p>
          </div>
        ) : (
          // Plain rows (no per-row animation): the Morph already fades the whole
          // view in, so animating rows here made them rise from the bottom on
          // entry and lag the list on leave.
          traces.map((t) => {
            const errs = errorCount(t);
            const toolCount = t.tools.length;
            return (
              <button
                key={t.traceId}
                type="button"
                className="fl-list-row"
                onClick={() => onSelect(t.traceId)}
              >
                <div className="fl-list-main">
                  <span className="fl-list-name">
                    <AgentBadge name={t.agentName ?? t.name} />
                    <span className="fl-list-agent">{t.agentName ?? t.name}</span>
                  </span>
                  <span className="fl-list-sub">
                    <ModelLogo
                      provider={t.provider}
                      modelId={t.model}
                      className="fl-model-icon"
                    />
                    <span className="fl-list-model">{formatModelName(t.model)}</span>
                    {toolCount > 0 && (
                      <span className="fl-list-tools">
                        · {toolCount} {toolCount === 1 ? "tool" : "tools"}
                      </span>
                    )}
                  </span>
                </div>
                {t.status === "running" ? (
                  <span className="fl-list-loading" title="Running">
                    <Diamond status="run" />
                  </span>
                ) : (
                  errs > 0 && (
                    <span
                      className="fl-err-badge"
                      title={`${errs} error${errs === 1 ? "" : "s"}`}
                    >
                      <WarnIcon />
                      {errs}
                    </span>
                  )
                )}
                <span className="fl-list-meta">
                  <span>{formatCost(t.totals?.costUsd)}</span>
                  <span>{formatDuration(traceDuration(t))}</span>
                </span>
                <ChevronRight />
              </button>
            );
          })
        )}
      </div>
    </div>
  );
}

/** One trace's live execution: header (back + model), tool armory, call tree, totals. */
function TraceDetail({
  trace,
  redact,
  onBack,
  onCollapse,
}: {
  trace: HudTrace;
  redact: boolean;
  onBack: () => void;
  onCollapse: () => void;
}) {
  const treeRef = useRef<HTMLDivElement>(null);
  const rowList = rows(trace);
  // Shared time axis for the waterfall bars.
  const now = Date.now();
  const tStart = trace.startedAt;
  const tDur = Math.max((trace.endedAt ?? now) - tStart, 1);
  const [open, setOpen] = useState<ReadonlySet<string>>(() => new Set());
  const toggle = (key: string) =>
    setOpen((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  useEffect(() => {
    const el = treeRef.current;
    if (el) el.scrollTo({ top: el.scrollHeight, behavior: "smooth" });
  }, [rowList.length]);

  return (
    <div className="fl-panel fl-panel-detail" role="dialog" aria-label="Foglamp trace">
      <div className="fl-header">
        <button
          type="button"
          className="fl-icon-btn"
          onClick={onBack}
          aria-label="Back to traces"
        >
          <ChevronLeft />
        </button>
        <div className="fl-title">
          <span className="fl-title-top">
            <AgentBadge name={trace.agentName ?? trace.name} />
            <b>{trace.agentName ?? trace.name}</b>
          </span>
          <span className="fl-model">
            <ModelLogo
              provider={trace.provider}
              modelId={trace.model}
              className="fl-model-icon"
              size={11}
            />
            {formatModelName(trace.model)}
          </span>
        </div>
        <Diamond status={statusKind(trace)} />
        <button
          type="button"
          className="fl-icon-btn"
          onClick={onCollapse}
          aria-label="Collapse"
        >
          <ChevronDown />
        </button>
      </div>

      {trace.toolNames.length > 0 && (
        <div className="fl-armory">
          {trace.toolNames.map((name) => {
            const used = trace.tools.some((t) => t.toolName === name);
            return (
              <span key={name} className={used ? "fl-chip used" : "fl-chip"}>
                <span className="fl-chip-ico">{toolGlyph(name)}</span>
                {name}
              </span>
            );
          })}
        </div>
      )}

      <div className="fl-tree" ref={treeRef}>
        {rowList.map((row) => {
          const isErr =
            row.kind === "step"
              ? row.step.status === "error"
              : row.tool.status === "error";
          const isOpen = open.has(row.key);
          return (
            <div
              key={row.key}
              className={`fl-row-item ${row.kind === "tool" ? "tool" : ""}`}
            >
              <button
                type="button"
                className={`fl-row ${isErr ? "err" : ""} ${isOpen ? "open" : ""}`}
                onClick={() => toggle(row.key)}
                aria-expanded={isOpen}
              >
                <WaterfallRow row={row} tStart={tStart} tDur={tDur} now={now} />
                <RowCaret open={isOpen} />
              </button>
              {/* Always rendered; the grid-rows 0fr→1fr trick animates open AND
                  close in pure CSS (height:auto is otherwise un-transitionable). */}
              <div className={`fl-row-detail ${isOpen ? "open" : ""}`}>
                <div className="fl-row-detail-inner">
                  {row.kind === "step" ? (
                    <StepDetail step={row.step} />
                  ) : (
                    <ToolDetail tool={row.tool} redact={redact} />
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <Footer trace={trace} />
    </div>
  );
}

function statusKind(t: HudTrace): StatusKind {
  if (t.status === "running") return "run";
  if (t.status === "error") return "err";
  return "";
}

function traceDuration(t: HudTrace): number {
  return t.totals?.durationMs ?? (t.endedAt ?? Date.now()) - t.startedAt;
}

// One waterfall row: [icon + label] [time bar on a shared axis] [duration].
function WaterfallRow({
  row,
  tStart,
  tDur,
  now,
}: {
  row: HudRow;
  tStart: number;
  tDur: number;
  now: number;
}) {
  const isStep = row.kind === "step";
  const status = isStep ? row.step.status : row.tool.status;
  const isErr = status === "error";
  const isRun = status === "running";
  const start = isStep ? row.step.startedAt : row.tool.startedAt;
  const explicit = isStep ? row.step.durationMs : row.tool.durationMs;
  const dur = explicit ?? Math.max(now - start, 0);
  const left = Math.min(Math.max(((start - tStart) / tDur) * 100, 0), 100);
  const width = Math.max((dur / tDur) * 100, 0);
  const kind = isStep ? "step" : "tool";
  return (
    <>
      <span className={`fl-wf-label ${kind}`}>
        <span className={`fl-wf-ico ${isErr ? "err" : ""}`}>
          {isErr ? <WarnIcon /> : isStep ? <StepGlyph /> : toolGlyph(row.tool.toolName)}
        </span>
        <b>{isStep ? `Step ${row.step.stepNumber + 1}` : row.tool.toolName}</b>
        <span className="fl-wf-lead" aria-hidden="true" />
      </span>
      <span className="fl-wf-track">
        <span
          className={`fl-wf-bar ${kind} ${isErr ? "err" : ""} ${isRun ? "run" : ""}`}
          style={{ left: `${left}%`, width: `${width}%` }}
        />
      </span>
      <span className="fl-wf-dur">{formatDuration(explicit ?? dur)}</span>
    </>
  );
}

