"use client";

import { Button } from "../ui/button";
import { cn } from "../lib/utils";
import { IconAlertTriangleFilled } from "@tabler/icons-react";
import { FoglampLink } from "../lib/link-context";

// Small sidebar card shown when the org nears (≥90%) or exceeds its monthly
// span quota. Reads the same usage endpoint as the Usage tab; polls so it
// clears once the period resets or the org upgrades.
export type QuotaUsage = { spans: { pct: number } };

/** Data-driven quota notice. The default empty mock keeps it hidden. */
export function QuotaCardView({
  usage = null,
  billingHref = "/settings/org?tab=billing",
}: {
  usage?: QuotaUsage | null;
  billingHref?: string;
}) {
  const pct = usage?.spans.pct;
  if (pct == null || pct < 0.9) return null;
  const over = pct >= 1;

  return (
    <div
      className={cn(
        "mb-1 flex flex-col gap-2 rounded-3xl squircle:rounded-[40px] corner-squircle p-3 px-3.5 text-xs",
        over
          ? "border-destructive/30 bg-destructive/10 text-destructive shadow-(--custom-shadow-destructive)"
          : "border-amber-500/10 bg-amber-500/10 text-amber-700 dark:text-amber-400 border"
      )}
    >
      <div className="flex gap-1.5 items-center">
        <IconAlertTriangleFilled className="size-3" />
        <span className="font-medium text-[13px]">
          {over
            ? "Span quota exceeded"
            : `${Math.round(pct * 100)}% of span quota used`}
        </span>
      </div>

      <div
        className={cn(
          "h-1 w-full overflow-hidden rounded-full mt-1",
          over ? "bg-destructive/20" : "bg-amber-500/20"
        )}
      >
        <div
          className={cn(
            "h-full rounded-full",
            over ? "bg-destructive" : "bg-amber-500"
          )}
          style={{ width: `${Math.min(pct, 1) * 100}%` }}
        />
      </div>
      {!over && (
        <span className="text-muted-foreground">
          Resets at the start of next month.
        </span>
      )}
      <Button
        variant="ghost-destructive"
        size="sm"
        className="mt-1 w-full"
        render={<FoglampLink href={billingHref} />}
      >
        {over ? "Upgrade now" : "Review billing"}
      </Button>
    </div>
  );
}

/** Backward-friendly short name for app shells using the original component name. */
export const QuotaCard = QuotaCardView;

/** Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted AS-IS from .reference/foglamp/apps/web/src/components/app/range-context.tsx; derived under Apache-2.0.
 */
"use client";

import { createContext, use, useEffect, useMemo, useState } from "react";

import {
	type RangeValue,
	defaultRange,
	exactRange,
	resolvePreset,
} from "../lib/range";

type RangeContextValue = {
	range: RangeValue;
	setRange: (range: RangeValue) => void;
};

const RangeContext = createContext<RangeContextValue | null>(null);

const STORAGE_KEY = "foglamp.range";

// Shared time-range filter so switching tabs keeps the same window. Relative
// presets are re-resolved to "now" on load; custom ranges restore their dates.
export function RangeProvider({ children }: { children: React.ReactNode }) {
	const [range, setRangeState] = useState<RangeValue>(() => defaultRange());

	useEffect(() => {
		if (typeof window === "undefined") return;
		const raw = localStorage.getItem(STORAGE_KEY);
		if (!raw) return;
		try {
			const v = JSON.parse(raw) as { key: string; from: string; to: string };
			if (v.key && v.key !== "custom") {
				setRangeState(resolvePreset(v.key));
			} else if (v.from && v.to) {
				// Exact restore keeps sub-day windows (chart drag-zooms) intact;
				// calendar ranges are stored day-snapped already, so they round-trip.
				setRangeState(exactRange(new Date(v.from), new Date(v.to)));
			}
		} catch {
			// ignore malformed storage
		}
	}, []);

	const setRange = (next: RangeValue) => {
		setRangeState(next);
		if (typeof window !== "undefined") {
			localStorage.setItem(
				STORAGE_KEY,
				JSON.stringify({
					key: next.key,
					from: next.from.toISOString(),
					to: next.to.toISOString(),
				}),
			);
		}
	};

	const value = useMemo<RangeContextValue>(
		() => ({ range, setRange }),
		[range],
	);

	return <RangeContext value={value}>{children}</RangeContext>;
}

export function useRange(): RangeContextValue {
	const ctx = use(RangeContext);
	if (!ctx) throw new Error("useRange must be used within RangeProvider");
	return ctx;
}

/** Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted AS-IS from .reference/foglamp/apps/web/src/components/theme-switcher.tsx; derived under Apache-2.0.
 */
"use client";

import {
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
} from "../ui/dropdown-menu";
import { cn } from "../lib/utils";
import { IconDeviceLaptop, IconMoon, IconSun } from "@tabler/icons-react";
import { motion } from "motion/react";
import { useTheme } from "next-themes";
import { useEffect, useId, useState } from "react";

// resolvedTheme is undefined during SSR and the first client render. We render a
// stable icon until mounted so the server and client agree; the real icon (and
// the active radio value) only appear once the theme is known on the client.
function useMounted() {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  return mounted;
}

// Same spring as the SDK-version toggle (instrument-empty-state), so segmented
// controls across the app glide identically.
const MORPH = { type: "spring", stiffness: 400, damping: 38 } as const;

const THEME_OPTIONS = [
  { value: "system", label: "System", icon: IconDeviceLaptop },
  { value: "light", label: "Light", icon: IconSun },
  { value: "dark", label: "Dark", icon: IconMoon },
] as const;

/**
 * Three-way theme control as a segmented pill (system / light / dark), matching
 * the SDK-version toggle. Switches instantly on click — no menu (used in the
 * marketing footer). The dropdown variant lives in {@link ThemeSubmenu}.
 */
export function ThemeSwitcher() {
  const { theme, setTheme } = useTheme();
  const mounted = useMounted();
  // Unique per instance so the sliding pill is scoped to this control.
  const pillId = useId();

  return (
    <div className="inline-flex  items-center">
      {THEME_OPTIONS.map((opt) => {
        // Track the chosen setting (theme), not the resolved value, so "System"
        // is its own selectable state. Nothing is active until mounted, so the
        // server and first client render agree.
        const active = mounted && theme === opt.value;
        const Icon = opt.icon;
        return (
          <button
            key={opt.value}
            type="button"
            aria-label={opt.label}
            aria-pressed={active}
            onClick={() => setTheme(opt.value)}
            className={cn(
              "relative flex size-7 cursor-pointer items-center justify-center rounded-full transition-colors",
              active
                ? "text-foreground"
                : "text-muted-foreground/60 hover:text-foreground"
            )}
          >
            {active && (
              <motion.span
                layoutId={pillId}
                transition={MORPH}
                className="absolute inset-0 rounded-full bg-input/50 shadow-(--custom-shadow) dark:bg-input/50"
              />
            )}
            <Icon className="relative z-10 size-3.5" />
          </button>
        );
      })}
    </div>
  );
}

/** Theme picker rendered as a submenu item, for use inside another dropdown. */
export function ThemeSubmenu() {
  const { theme, setTheme, resolvedTheme } = useTheme();
  const mounted = useMounted();

  return (
    <DropdownMenuSub>
      <DropdownMenuSubTrigger>
        {mounted && resolvedTheme === "dark" ? <IconMoon /> : <IconSun />}
        Theme
      </DropdownMenuSubTrigger>
      <DropdownMenuSubContent>
        <DropdownMenuRadioGroup
          value={mounted ? theme : undefined}
          onValueChange={setTheme}
        >
          <DropdownMenuRadioItem value="light">
            <IconSun />
            Light
          </DropdownMenuRadioItem>
          <DropdownMenuRadioItem value="dark">
            <IconMoon />
            Dark
          </DropdownMenuRadioItem>
          <DropdownMenuRadioItem value="system">
            <IconDeviceLaptop />
            System
          </DropdownMenuRadioItem>
        </DropdownMenuRadioGroup>
      </DropdownMenuSubContent>
    </DropdownMenuSub>
  );
}
